import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';

const values = [
  { icon: '🕊️', title: 'Compassion First', desc: 'Every session begins with deep, unconditional empathy and zero judgment.' },
  { icon: '🔑', title: 'Emotional Alchemy', desc: 'We believe pain, when witnessed with love, transforms into profound wisdom.' },
  { icon: '🌿', title: 'Safe Sanctuary', desc: 'Your emotional world is sacred here — held with the utmost care and confidentiality.' },
  { icon: '✨', title: 'Empowered Growth', desc: 'We walk beside you — never ahead — as you discover your own inner strength.' },
];

const stats = [
  { number: '12+', label: 'Years of Experience' },
  { number: '500+', label: 'Clients Supported' },
  { number: '98%', label: 'Client Satisfaction' },
  { number: '3', label: 'Therapy Modalities' },
];

const testimonial = {
  quote: 'Working with Amara was the turning point I never knew I needed. For the first time in years, I felt truly seen — not fixed, just understood.',
  author: 'A. Patel',
  role: 'Client, 2023',
};

/* ─── Shared button styles ─── */
const darkBtn = {
  background: 'linear-gradient(135deg, #2C1E28, #3D2B38)',
  color: '#F5EDE8',
  border: '1px solid rgba(255,255,255,0.08)',
  borderRadius: '6px',
  padding: '15px 38px',
  fontFamily: 'Manrope',
  fontSize: '0.88rem',
  fontWeight: 700,
  letterSpacing: '0.06em',
  textTransform: 'uppercase',
  cursor: 'pointer',
  boxShadow: '0 4px 20px rgba(44,30,40,0.35)',
};

const outlineBtn = {
  background: 'transparent',
  color: '#3D2B38',
  border: '1.5px solid #3D2B38',
  borderRadius: '6px',
  padding: '14px 36px',
  fontFamily: 'Manrope',
  fontSize: '0.88rem',
  fontWeight: 700,
  letterSpacing: '0.06em',
  textTransform: 'uppercase',
  cursor: 'pointer',
};

const AboutPage = () => (
  <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>

    {/* ── Hero ── */}
    <section style={{
      minHeight: '62vh',
      display: 'flex',
      alignItems: 'center',
      padding: '140px 2rem 80px',
      position: 'relative',
      overflow: 'hidden',
      zIndex: 2,
    }}>
      {/* Background accent blobs */}
      <div style={{
        position: 'absolute', top: 0, right: 0, width: '55%', height: '100%',
        background: 'radial-gradient(ellipse at right center, rgba(221,183,176,0.14) 0%, transparent 70%)',
        zIndex: 1,
      }} />
      <div style={{
        position: 'absolute', bottom: '-60px', left: '-80px', width: '400px', height: '400px',
        background: 'radial-gradient(circle, rgba(180,200,175,0.1) 0%, transparent 70%)',
        zIndex: 1,
      }} />

      <div style={{ maxWidth: '860px', margin: '0 auto', textAlign: 'center', position: 'relative', zIndex: 2 }}>
        <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.8 }}>

          {/* Eyebrow */}
          <div style={{
            display: 'inline-flex', alignItems: 'center', gap: '0.6rem',
            fontFamily: 'Manrope', fontSize: '0.72rem', letterSpacing: '0.18em',
            color: '#8A7070', textTransform: 'uppercase', marginBottom: '1.2rem',
          }}>
            <span style={{ display: 'inline-block', width: '28px', height: '1px', background: '#C4A89E' }} />
            Our Philosophy
            <span style={{ display: 'inline-block', width: '28px', height: '1px', background: '#C4A89E' }} />
          </div>

          <h1 style={{
            fontFamily: 'Cormorant Garamond, serif',
            fontSize: 'clamp(2.6rem, 5.5vw, 4.2rem)',
            fontWeight: 600,
            color: '#2C1E28',
            lineHeight: 1.18,
            marginBottom: '1.6rem',
            letterSpacing: '-0.01em',
          }}>
            The Art of<br />Emotional Alchemy
          </h1>

          <p style={{
            fontFamily: 'Manrope', fontSize: '1rem', color: '#7A606E',
            lineHeight: 1.95, maxWidth: '640px', margin: '0 auto 2.2rem',
          }}>
            We believe every emotion — no matter how overwhelming — carries a hidden message,
            a gift waiting to be unwrapped with patience and love. Emotional alchemy is the
            sacred process of turning your pain into your greatest power.
          </p>

          {/* CTA row in hero */}
          <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center', flexWrap: 'wrap' }}>
            <Link to="/book">
              <motion.button
                whileHover={{ scale: 1.03, boxShadow: '0 8px 32px rgba(44,30,40,0.45)' }}
                whileTap={{ scale: 0.98 }}
                style={darkBtn}
              >
                Book a Session
              </motion.button>
            </Link>
            <Link to="/services">
              <motion.button
                whileHover={{ background: 'rgba(44,30,40,0.06)' }}
                whileTap={{ scale: 0.98 }}
                style={outlineBtn}
              >
                Our Services
              </motion.button>
            </Link>
          </div>

        </motion.div>
      </div>
    </section>

    {/* ── Stats Bar ── */}
    <section style={{
      background: '#2C1E28',
      padding: '2.8rem 2rem',
      position: 'relative',
      zIndex: 2,
    }}>
      <div style={{
        maxWidth: '960px', margin: '0 auto',
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
        gap: '2rem',
        textAlign: 'center',
      }}>
        {stats.map((s, i) => (
          <motion.div
            key={s.label}
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: i * 0.1 }}
          >
            <div style={{
              fontFamily: 'Cormorant Garamond, serif',
              fontSize: '2.8rem',
              fontWeight: 600,
              color: '#EDD5D0',
              lineHeight: 1,
              marginBottom: '0.4rem',
            }}>
              {s.number}
            </div>
            <div style={{
              fontFamily: 'Manrope',
              fontSize: '0.73rem',
              letterSpacing: '0.12em',
              color: '#B8A0AA',
              textTransform: 'uppercase',
            }}>
              {s.label}
            </div>
          </motion.div>
        ))}
      </div>
    </section>

    {/* ── Story ── */}
    <section style={{ padding: '100px 2rem', position: 'relative', zIndex: 2 }}>
      <div style={{ maxWidth: '1100px', margin: '0 auto' }}>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
          gap: '4rem',
          alignItems: 'center',
        }}>

          {/* Therapist Card */}
          <motion.div
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            style={{
              background: 'rgba(255,253,252,0.85)',
              backdropFilter: 'blur(20px)',
              border: '1px solid rgba(221,183,176,0.25)',
              borderRadius: '20px',
              padding: '2.8rem 2.2rem',
              textAlign: 'center',
              boxShadow: '0 2px 40px rgba(44,30,40,0.06)',
            }}
          >
            {/* Avatar with glow ring */}
            <div style={{ position: 'relative', width: '124px', margin: '0 auto 1.8rem' }}>
              <motion.div
                animate={{ boxShadow: ['0 0 0 0 rgba(221,183,176,0.25)', '0 0 0 12px rgba(221,183,176,0)', '0 0 0 0 rgba(221,183,176,0)'] }}
                transition={{ repeat: Infinity, duration: 2.8, ease: 'easeOut' }}
                style={{
                  width: '124px', height: '124px', borderRadius: '50%',
                  background: 'linear-gradient(135deg, #EDD5D0, #D4DCCF)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: '3rem',
                  border: '3px solid rgba(221,183,176,0.45)',
                }}
              >
                🌸
              </motion.div>
            </div>

            <h3 style={{
              fontFamily: 'Cormorant Garamond, serif',
              fontSize: '1.55rem', fontWeight: 600, color: '#2C1E28', marginBottom: '0.25rem',
            }}>
              Dr. Amara Linden
            </h3>
            <div style={{
              fontFamily: 'Manrope', fontSize: '0.72rem',
              color: '#A89098', letterSpacing: '0.1em', marginBottom: '1.2rem', textTransform: 'uppercase',
            }}>
              Licensed Therapist · Emotional Wellness Expert
            </div>

            {/* Divider */}
            <div style={{ height: '1px', background: 'rgba(221,183,176,0.3)', margin: '0 auto 1.2rem', width: '60px' }} />

            <p style={{ fontFamily: 'Manrope', fontSize: '0.87rem', color: '#7A606E', lineHeight: 1.85 }}>
              With over 12 years of experience in trauma-informed care, emotional healing,
              and mindfulness therapy, Amara creates a space where every client feels truly
              seen, heard, and deeply understood.
            </p>

            {/* Credential Tags */}
            <div style={{ display: 'flex', justifyContent: 'center', gap: '0.6rem', marginTop: '1.6rem', flexWrap: 'wrap' }}>
              {['Trauma-Informed', 'CBT Certified', 'Mindfulness'].map(tag => (
                <div key={tag} style={{
                  background: '#2C1E28',
                  color: '#EDD5D0',
                  borderRadius: '4px',
                  padding: '5px 12px',
                  fontFamily: 'Manrope',
                  fontSize: '0.68rem',
                  fontWeight: 600,
                  letterSpacing: '0.07em',
                  textTransform: 'uppercase',
                }}>
                  {tag}
                </div>
              ))}
            </div>
          </motion.div>

          {/* Story Text */}
          <motion.div
            initial={{ opacity: 0, x: 30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
          >
            {/* Section label */}
            <div style={{
              fontFamily: 'Manrope', fontSize: '0.72rem', letterSpacing: '0.16em',
              color: '#A89098', textTransform: 'uppercase', marginBottom: '1rem',
              display: 'flex', alignItems: 'center', gap: '0.5rem',
            }}>
              <span style={{ width: '20px', height: '1px', background: '#C4A89E', display: 'inline-block' }} />
              Our Story
            </div>

            <h2 style={{
              fontFamily: 'Cormorant Garamond, serif',
              fontSize: 'clamp(1.9rem, 3vw, 2.6rem)',
              fontWeight: 600, color: '#2C1E28', lineHeight: 1.25, marginBottom: '1.6rem',
            }}>
              Why Struvive Emolings<br />Was Born
            </h2>

            <p style={{ fontFamily: 'Manrope', fontSize: '0.94rem', color: '#7A606E', lineHeight: 1.95, marginBottom: '1.2rem' }}>
              Struvive Emolings was created from a deep belief that emotional wellbeing is not a luxury —
              it is a fundamental human need. Too many people walk through life carrying invisible weights
              they were never taught to put down.
            </p>
            <p style={{ fontFamily: 'Manrope', fontSize: '0.94rem', color: '#7A606E', lineHeight: 1.95, marginBottom: '1.2rem' }}>
              Our name holds our mission: <em style={{ color: '#3D2B38', fontStyle: 'normal', fontWeight: 600 }}>"Struvive"</em> — to strive and thrive —
              and <em style={{ color: '#3D2B38', fontStyle: 'normal', fontWeight: 600 }}>"Emolings"</em> — emotional beings on a journey of becoming.
              Together: thriving through emotional growth.
            </p>
            <p style={{ fontFamily: 'Manrope', fontSize: '0.94rem', color: '#7A606E', lineHeight: 1.95 }}>
              We are a sanctuary for those brave enough to look inward, for those ready to transform
              their emotional landscape from survival into flourishing.
            </p>

            {/* Inline CTA */}
            <div style={{ marginTop: '2.2rem' }}>
              <Link to="/book">
                <motion.button
                  whileHover={{ scale: 1.03, boxShadow: '0 8px 32px rgba(44,30,40,0.45)' }}
                  whileTap={{ scale: 0.98 }}
                  style={darkBtn}
                >
                  Begin Your Journey
                </motion.button>
              </Link>
            </div>
          </motion.div>

        </div>
      </div>
    </section>

    {/* ── Testimonial Strip ── */}
    <section style={{
      padding: '64px 2rem',
      background: 'linear-gradient(135deg, #F5EDE8 0%, #EEF0EC 100%)',
      position: 'relative', zIndex: 2,
      borderTop: '1px solid rgba(221,183,176,0.3)',
      borderBottom: '1px solid rgba(221,183,176,0.3)',
    }}>
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        style={{ maxWidth: '720px', margin: '0 auto', textAlign: 'center' }}
      >
        <div style={{ fontSize: '2.4rem', color: '#C4A89E', lineHeight: 1, marginBottom: '1.2rem', fontFamily: 'Georgia, serif' }}>"</div>
        <p style={{
          fontFamily: 'Cormorant Garamond, serif',
          fontSize: 'clamp(1.15rem, 2.5vw, 1.5rem)',
          color: '#3D2B38',
          fontWeight: 500,
          lineHeight: 1.65,
          fontStyle: 'italic',
          marginBottom: '1.5rem',
        }}>
          {testimonial.quote}
        </p>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.8rem' }}>
          <div style={{ width: '32px', height: '1px', background: '#C4A89E' }} />
          <div>
            <span style={{ fontFamily: 'Manrope', fontSize: '0.78rem', fontWeight: 700, color: '#2C1E28', letterSpacing: '0.08em' }}>
              {testimonial.author}
            </span>
            <span style={{ fontFamily: 'Manrope', fontSize: '0.73rem', color: '#A89098', marginLeft: '0.5rem' }}>
              — {testimonial.role}
            </span>
          </div>
          <div style={{ width: '32px', height: '1px', background: '#C4A89E' }} />
        </div>
